"""Execution engine for minisql.

The engine loads a single CSV table, applies the query clauses in order, and
returns a :class:`Result`.  Parsing and expression evaluation live in the
sibling ``parser`` and ``evaluator`` modules.
"""

import csv
import functools
import os
import re

from .ast import Column, Literal, contains_aggregate
from .errors import QueryError
from .evaluator import (
    compare_values,
    evaluate,
    validate_expression,
    validate_grouped_expression,
)
from .parser import parse


_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")
# A bare ordinal in ORDER BY must be made only of decimal digits.  In
# particular "-1" and "(2)" are ordinary expressions, not ordinals.
_BARE_INT_RE = re.compile(r"[0-9]+")


class Result:
    """The outcome of running a query."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


def _convert_field(value):
    """Convert one CSV field to a minisql value."""

    if value == "":
        return None
    if _INT_RE.fullmatch(value):
        return int(value)
    if _FLOAT_RE.fullmatch(value):
        return float(value)
    return value


def _load_table(directory, table):
    """Load ``<table>.csv`` and return ``(headers, rows)``.

    ``headers`` keeps the spelling from the file.  Every row is a dict keyed
    by lowercased header names.
    """

    path = os.path.join(directory, table + ".csv")
    try:
        handle = open(path, "r", encoding="utf-8", newline="")
    except OSError as exc:
        raise QueryError(
            'cannot open table "%s": %s' % (table, exc)
        ) from exc

    with handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise QueryError(
                'table "%s" has no header row' % table
            ) from None
        except (csv.Error, OSError, UnicodeDecodeError) as exc:
            raise QueryError(
                'cannot read table "%s": %s' % (table, exc)
            ) from exc

        if not header or all(name == "" for name in header):
            raise QueryError('table "%s" has no column names' % table)

        lowered = [name.lower() for name in header]
        rows = []
        try:
            for record in reader:
                if len(record) != len(header):
                    raise QueryError(
                        'table "%s" row %d has %d fields, expected %d'
                        % (table, reader.line_num, len(record), len(header))
                    )
                rows.append(
                    {
                        lowered[index]: _convert_field(record[index])
                        for index in range(len(header))
                    }
                )
        except (csv.Error, OSError, UnicodeDecodeError) as exc:
            raise QueryError(
                'cannot read table "%s": %s' % (table, exc)
            ) from exc

    return header, rows


def _header_lookup(headers):
    """Map lowercased header names to their original spelling."""

    lookup = {}
    for name in headers:
        lookup.setdefault(name.lower(), name)
    return lookup


def _is_grouped(query):
    if query.group_by:
        return True
    for item in query.items:
        if contains_aggregate(item.expr):
            return True
    if contains_aggregate(query.having):
        return True
    for item in query.order_by:
        if contains_aggregate(item.expr):
            return True
    return False


def _output_name(item, lookup):
    if item.alias is not None:
        return item.alias
    expr = item.expr
    if isinstance(expr, Column):
        actual = lookup.get(expr.name.lower())
        if actual is not None:
            return actual
    return expr.text


def _output_index(name, columns):
    lowered = name.lower()
    for index, column in enumerate(columns):
        if column.lower() == lowered:
            return index
    return None


class _OrderSpec:
    """How to obtain the value for one ORDER BY item."""

    __slots__ = ("kind", "index", "expr", "desc")

    def __init__(self, kind, index=None, expr=None, desc=False):
        self.kind = kind
        self.index = index
        self.expr = expr
        self.desc = desc


def _resolve_order_item(item, columns, headers, grouped, group_by):
    expr = item.expr

    if isinstance(expr, Column):
        index = _output_index(expr.name, columns)
        if index is not None:
            return _OrderSpec("output", index=index, desc=item.desc)

    if (
        isinstance(expr, Literal)
        and isinstance(expr.value, int)
        and not isinstance(expr.value, bool)
    ):
        text = expr.text or ""
        if _BARE_INT_RE.fullmatch(text):
            ordinal = int(text)
            if ordinal == expr.value:
                if ordinal < 1 or ordinal > len(columns):
                    raise QueryError(
                        "ORDER BY position %d is out of range" % ordinal
                    )
                return _OrderSpec(
                    "output", index=ordinal - 1, desc=item.desc
                )

    # It is an expression over the source rows (or groups).
    validate_expression(expr, headers, allow_aggregate=True)
    if grouped:
        validate_grouped_expression(expr, group_by)
    return _OrderSpec("expression", expr=expr, desc=item.desc)


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""

    query = parse(sql)
    base = os.fspath(directory)
    headers, source_rows = _load_table(base, query.table)
    lookup = _header_lookup(headers)

    # Static validation.  Doing this before touching any rows means unknown
    # columns and misplaced aggregates are reported for empty tables too.
    if query.where is not None:
        validate_expression(query.where, headers, allow_aggregate=False)
    for expr in query.group_by:
        validate_expression(expr, headers, allow_aggregate=False)
    if not query.star:
        for item in query.items:
            validate_expression(item.expr, headers, allow_aggregate=True)
    if query.having is not None:
        validate_expression(query.having, headers, allow_aggregate=True)

    if query.limit is not None and query.limit < 0:
        raise QueryError("LIMIT must not be negative")
    if query.offset is not None and query.offset < 0:
        raise QueryError("OFFSET must not be negative")

    # WHERE ------------------------------------------------------------
    rows = source_rows
    if query.where is not None:
        rows = [row for row in rows if evaluate(query.where, row) is True]

    grouped = _is_grouped(query)

    # Build one execution unit per output row.  A unit is
    # ``(representative_row, group_or_None)``.
    if not grouped:
        units = [(row, None) for row in rows]
    elif query.group_by:
        groups = []  # list of (key, rows), in first-seen order
        for row in rows:
            key = tuple(evaluate(expr, row) for expr in query.group_by)
            for group_key, group_rows in groups:
                if group_key == key:
                    group_rows.append(row)
                    break
            else:
                groups.append((key, [row]))
        units = [(group_rows[0], group_rows) for _, group_rows in groups]
    else:
        # No GROUP BY: all rows (possibly none) make a single group.
        units = [(rows[0] if rows else None, rows)]

    # Expand the select list.  ``*`` keeps the CSV header spelling.
    if query.star:
        output_columns = list(headers)
        output_exprs = [Column(text=name, name=name) for name in headers]
    else:
        output_columns = [
            _output_name(item, lookup) for item in query.items
        ]
        output_exprs = [item.expr for item in query.items]

    # Grouped-query column rules.
    if grouped:
        for expr in output_exprs:
            validate_grouped_expression(expr, query.group_by)
        if query.having is not None:
            validate_grouped_expression(query.having, query.group_by)

    # HAVING -----------------------------------------------------------
    if query.having is not None:
        units = [
            unit
            for unit in units
            if evaluate(query.having, unit[0], unit[1]) is True
        ]

    # Projection -------------------------------------------------------
    # Each record keeps its source unit so ORDER BY expressions that are not
    # output columns can still be evaluated.
    records = []
    for representative, group in units:
        values = tuple(
            evaluate(expr, representative, group) for expr in output_exprs
        )
        records.append((values, (representative, group)))

    # DISTINCT ---------------------------------------------------------
    if query.distinct:
        seen = set()
        distinct_records = []
        for values, unit in records:
            if values in seen:
                continue
            seen.add(values)
            distinct_records.append((values, unit))
        records = distinct_records

    # ORDER BY ---------------------------------------------------------
    if query.order_by:
        specs = [
            _resolve_order_item(
                item, output_columns, headers, grouped, query.group_by
            )
            for item in query.order_by
        ]
        sort_keys = []
        for values, unit in records:
            row_keys = []
            for spec in specs:
                if spec.kind == "output":
                    row_keys.append(values[spec.index])
                else:
                    row_keys.append(
                        evaluate(spec.expr, unit[0], unit[1])
                    )
            sort_keys.append(row_keys)

        def compare(left, right):
            for spec, left_key, right_key in zip(
                specs, sort_keys[left], sort_keys[right]
            ):
                if left_key is None and right_key is None:
                    continue
                if left_key is None:
                    return -1 if not spec.desc else 1
                if right_key is None:
                    return 1 if not spec.desc else -1
                result = compare_values(left_key, right_key)
                if result:
                    return result if not spec.desc else -result
            return 0

        order = sorted(
            range(len(records)), key=functools.cmp_to_key(compare)
        )
        records = [records[index] for index in order]

    # LIMIT / OFFSET ---------------------------------------------------
    offset = query.offset or 0
    if query.limit is None:
        selected = records[offset:]
    else:
        selected = records[offset : offset + query.limit]

    return Result(
        output_columns,
        [values for values, _unit in selected],
    )

